window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e04ccc609db691e8"]={"versions": [{"id": "FIG-e04ccc609db691e8", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Funktions- und Datenflussdiagramm des Signalverarbeitungs- und Routingpfads innerhalb des AUTOSAR Classic COM-Moduls (SWS COM). Das Diagramm stellt den logischen Signalfluss für Sende- und Weiterleitungspfade (Signal-based Gateway) bezogen auf die Zusammensetzung einer ausgehenden Sende-I-PDU (<code>IPDU_k</code>) sowie die Bestimmung ihres Übertragungsmodus über den Transmission Mode Selector (TMS) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Eingangssignale</strong>:</li>\n<li><code>Signal 1</code>, <code>Signal 2</code>: Senderseitige Signale aus der oberen Softwareschicht (RTE bzw. SW-C).</li>\n<li>RX-Signalpfade: <code>From RX side – after endianess conversion and sign extension</code> sowie <code>From RX side – before endianess conversion and sign extension</code>.</li>\n<li><strong>Verarbeitungseinheiten</strong>:</li>\n<li><code>Signal based gateway</code>: Routing-Komponente zur Weiterleitung von RX nach TX mit getrennten internen Durchleitungen.</li>\n<li><code>Evaluation of TRANSMISSION MODE Condition C(s_i, IPDU_k)</code> / <code>C(s_j, IPDU_k)</code>: Filter- und Bedingungsauswertungsblöcke je Signal zur TMS-Bestimmung (entsprechend Filtermechanismen aus OSEK COM 3.03), jeweils mit booleschen Ausgängen <code>true</code> und <code>false</code>.</li>\n<li><code>Evaluation of TRANSMISSION MODE Selector (TMS) for I-PDU</code>: Sammel- und Auswahllogik zur Aggregation der Signalzustände für den I-PDU-Sendemodus.</li>\n<li><strong>Zielstrukturen / Datenpfade</strong>:</li>\n<li><code>update signal in I-PDU</code>: Pfade zum Schreiben des Signalwerts in das I-PDU-Pufferlayout.</li>\n<li>Sende-I-PDU (<code>IPDU_k</code>): Aggregiertes PDU-Layout bestehend aus den Signalfeldern <code>Signal 1</code>, <code>Signal 2</code> und <code>Signal 3</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Bei Bereitstellung eines Sendesignals (<code>Signal 1</code>, <code>Signal 2</code>) verzweigt der Signalfluss: Ein Zweig aktualisiert das Signal direkt im PDU-Puffer (<code>update signal in I-PDU</code>), der andere speist den Block zur Auswertung der Transmission-Mode-Bedingung <code>C(s, IPDU_k)</code>.</li>\n<li>Bei gerouteten Signalen über das <code>Signal based gateway</code> wird das RX-Signal nach Endianness-Konvertierung und Vorzeichenerweiterung der Bedingungsauswertung <code>C(s_j, IPDU_k)</code> zugeführt; das RX-Signal vor Endianness-Konvertierung und Vorzeichenerweiterung wird parallel direkt in die I-PDU (<code>Signal 3</code>) geschrieben.</li>\n<li>Die Bedingungsauswertungen liefern jeweils einen booleschen Status (<code>true</code> / <code>false</code>) an die vertikale Aggregationsschiene.</li>\n<li>Die Aggregationsschiene leitet die Einzelauswertungen an den <code>Evaluation of TRANSMISSION MODE Selector (TMS) for I-PDU</code> weiter.</li>\n<li>Der TMS bestimmt den aktuellen Übertragungsmodus der Sende-I-PDU und steuert deren Gesamtsendung.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Diagramm definiert die funktionale Kopplung von Signalaktualisierung (<code>update signal in I-PDU</code>) und Übertragungsmodusselektion (TMS).</li>\n<li>Verdeutlicht die architektonische Regelung für Signal-Gatewaying: Filterbedingungen für den Sendemodus basieren auf dem gewandelten Signalwert (nach Endianness/Vorzeichenerweiterung), während das Schreiben in die I-PDU direkt mit den Roh-/Eingangsdaten (vor Endianness-Konvertierung) erfolgen kann.</li>\n<li>Bedingungen entsprechen den Filterdefinitionen nach OSEK COM 3.03.</li>\n</ul>"}, {"id": "FIG-50f006e5c8dd4f97", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Funktions- und Datenflussdiagramm des Signalverarbeitungs- und Routingpfads innerhalb des AUTOSAR Classic COM-Moduls (SWS COM). Das Diagramm stellt den logischen Signalfluss für Sende- und Weiterleitungspfade (Signal-based Gateway) bezogen auf die Zusammensetzung einer ausgehenden Sende-I-PDU (<code>IPDU_k</code>) sowie die Bestimmung ihres Übertragungsmodus über den Transmission Mode Selector (TMS) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Eingangssignale</strong>:</li>\n<li><code>Signal 1</code>, <code>Signal 2</code>: Senderseitige Signale aus der oberen Softwareschicht (RTE bzw. SW-C).</li>\n<li>RX-Signalpfade: <code>From RX side – after endianness conversion and sign extension</code> sowie <code>From RX side – before endianness conversion and sign extension</code>.</li>\n<li><strong>Verarbeitungseinheiten</strong>:</li>\n<li><code>Signal based gateway</code>: Routing-Komponente zur Weiterleitung empfangener Signale auf die TX-Seite. Das Gateway nimmt das konvertierte RX-Signal auf und stellt einen konsolidierten TX-Ausgang bereit.</li>\n<li><code>Evaluation of TRANSMISSION MODE Condition C(s_i, IPDU_k)</code> / <code>C(s_j, IPDU_k)</code>: Filter- und Bedingungsauswertungsblöcke je Signal zur TMS-Bestimmung (entsprechend Filtermechanismen aus OSEK COM 3.03), jeweils mit booleschen Ausgängen <code>true</code> und <code>false</code>.</li>\n<li><code>Evaluation of TRANSMISSION MODE Selector (TMS) for I-PDU</code>: Sammel- und Auswahllogik zur Aggregation der Signalzustände für den I-PDU-Sendemodus.</li>\n<li><strong>Zielstrukturen / Datenpfade</strong>:</li>\n<li><code>update signal in I-PDU</code>: Pfade zum Schreiben des Signalwerts in das I-PDU-Pufferlayout.</li>\n<li>Sende-I-PDU (<code>IPDU_k</code>): Aggregiertes PDU-Layout bestehend aus den Signalfeldern <code>Signal 1</code>, <code>Signal 2</code> und <code>Signal 3</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Bei Bereitstellung eines Sendesignals (<code>Signal 1</code>, <code>Signal 2</code>) verzweigt der Signalfluss: Ein Zweig aktualisiert das Signal direkt im PDU-Puffer (<code>update signal in I-PDU</code>), der andere speist den Block zur Auswertung der Transmission-Mode-Bedingung <code>C(s, IPDU_k)</code>.</li>\n<li>Das Signal-Gateway nimmt das gewandelte Signal (<code>From RX side – after endianness conversion and sign extension</code>) auf und speist über seinen TX-Ausgang sowohl die Bedingungsauswertung <code>C(s_j, IPDU_k)</code> als auch den Pufferaktualisierungspfad (<code>update signal in I-PDU</code>) für <code>Signal 3</code>. Der Pfad vor Konvertierung läuft als RX-Eingang ohne interne Durchleitung in den Gateway-Block.</li>\n<li>Die Bedingungsauswertungen liefern jeweils einen booleschen Status (<code>true</code> / <code>false</code>) an die vertikale Aggregationsschiene.</li>\n<li>Die Aggregationsschiene leitet die Einzelauswertungen an den <code>Evaluation of TRANSMISSION MODE Selector (TMS) for I-PDU</code> weiter.</li>\n<li>Der TMS bestimmt den aktuellen Übertragungsmodus der Sende-I-PDU und steuert deren Gesamtsendung.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Diagramm definiert die funktionale Kopplung von Signalaktualisierung (<code>update signal in I-PDU</code>) und Übertragungsmodusselektion (TMS).</li>\n<li>Zeigt das Routingverhalten im Signal-Gateway für Weiterleitungssignale auf TX-I-PDUs.</li>\n<li>Bedingungen zur Bestimmung des Transmission Mode Selector basieren auf den Filterdefinitionen nach OSEK COM 3.03.</li>\n</ul>"}, {"id": "FIG-0b01ac56cc9b1123", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Funktions- und Datenflussdiagramm des Signalverarbeitungs- und Routingpfads innerhalb des AUTOSAR Classic COM-Moduls (SWS COM). Das Diagramm stellt den logischen Signalfluss für Sende- und Weiterleitungspfade (Signal-based Gateway) bezogen auf die Zusammensetzung einer ausgehenden Sende-I-PDU (<code>IPDU_k</code>) sowie die Bestimmung ihres Übertragungsmodus über den Transmission Mode Selector (TMS) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Eingangssignale</strong>:</li>\n<li><code>Signal 1</code>, <code>Signal 2</code>: Senderseitige Signale aus der oberen Softwareschicht (RTE bzw. SW-C).</li>\n<li>RX-Signalpfade: <code>From RX side – after endianness conversion and sign extension</code> sowie <code>From RX side – before endianness conversion and sign extension</code>.</li>\n<li><strong>Verarbeitungseinheiten</strong>:</li>\n<li><code>Signal based gateway</code>: Routing-Komponente zur Weiterleitung empfangener Signale auf die TX-Seite. Das Gateway nimmt das konvertierte RX-Signal auf und stellt einen konsolidierten TX-Ausgang bereit.</li>\n<li><code>Evaluation of TRANSMISSION MODE Condition C(s_i, IPDU_k)</code> / <code>C(s_j, IPDU_k)</code>: Filter- und Bedingungsauswertungsblöcke je Signal zur TMS-Bestimmung (entsprechend Filtermechanismen aus OSEK COM 3.03), jeweils mit booleschen Ausgängen <code>true</code> und <code>false</code>.</li>\n<li><code>Evaluation of TRANSMISSION MODE Selector (TMS) for I-PDU</code>: Sammel- und Auswahllogik zur Aggregation der Signalzustände für den I-PDU-Sendemodus.</li>\n<li><strong>Zielstrukturen / Datenpfade</strong>:</li>\n<li><code>update signal in I-PDU</code>: Pfade zum Schreiben des Signalwerts in das I-PDU-Pufferlayout.</li>\n<li>Sende-I-PDU (<code>IPDU_k</code>): Aggregiertes PDU-Layout bestehend aus den Signalfeldern <code>Signal 1</code>, <code>Signal 2</code> und <code>Signal 3</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Bei Bereitstellung eines Sendesignals (<code>Signal 1</code>, <code>Signal 2</code>) verzweigt der Signalfluss: Ein Zweig aktualisiert das Signal direkt im PDU-Puffer (<code>update signal in I-PDU</code>), der andere speist den Block zur Auswertung der Transmission-Mode-Bedingung <code>C(s, IPDU_k)</code>.</li>\n<li>Das Signal-Gateway nimmt das gewandelte Signal (<code>From RX side – after endianness conversion and sign extension</code>) auf und speist über seinen TX-Ausgang sowohl die Bedingungsauswertung <code>C(s_j, IPDU_k)</code> als auch den Pufferaktualisierungspfad (<code>update signal in I-PDU</code>) für <code>Signal 3</code>. Der Pfad vor Konvertierung läuft als RX-Eingang ohne interne Durchleitung in den Gateway-Block.</li>\n<li>Die Bedingungsauswertungen liefern jeweils einen booleschen Status (<code>true</code> / <code>false</code>) an die vertikale Aggregationsschiene.</li>\n<li>Die Aggregationsschiene leitet die Einzelauswertungen an den <code>Evaluation of TRANSMISSION MODE Selector (TMS) for I-PDU</code> weiter.</li>\n<li>Der TMS bestimmt den aktuellen Übertragungsmodus der Sende-I-PDU und steuert deren Gesamtsendung.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Diagramm definiert die funktionale Kopplung von Signalaktualisierung (<code>update signal in I-PDU</code>) und Übertragungsmodusselektion (TMS).</li>\n<li>Zeigt das Routingverhalten im Signal-Gateway für Weiterleitungssignale auf TX-I-PDUs.</li>\n<li>Bedingungen zur Bestimmung des Transmission Mode Selector basieren auf den Filterdefinitionen nach OSEK COM 3.03.</li>\n</ul>"}, {"id": "FIG-4db611d5ba06f74d", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Funktions- und Datenflussdiagramm des Signalverarbeitungs- und Routingpfads innerhalb des AUTOSAR Classic COM-Moduls (SWS COM). Das Diagramm stellt den logischen Signalfluss für Sende- und Weiterleitungspfade (Signal-based Gateway) bezogen auf die Zusammensetzung einer ausgehenden Sende-I-PDU (<code>IPDU_k</code>) sowie die Bestimmung ihres Übertragungsmodus über den Transmission Mode Selector (TMS) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Eingangssignale</strong>:</li>\n<li><code>Signal 1</code>, <code>Signal 2</code>: Senderseitige Signale aus der oberen Softwareschicht (RTE bzw. SW-C).</li>\n<li>RX-Signalpfade: <code>From RX side – after endianness conversion and sign extension</code> sowie <code>From RX side – before endianness conversion and sign extension</code>.</li>\n<li><strong>Verarbeitungseinheiten</strong>:</li>\n<li><code>Signal based gateway</code>: Routing-Komponente zur Weiterleitung empfangener Signale auf die TX-Seite. Das Gateway nimmt das konvertierte RX-Signal auf und stellt einen konsolidierten TX-Ausgang bereit.</li>\n<li><code>Evaluation of TRANSMISSION MODE Condition C(s_i, IPDU_k)</code> / <code>C(s_j, IPDU_k)</code>: Filter- und Bedingungsauswertungsblöcke je Signal zur TMS-Bestimmung (entsprechend Filtermechanismen aus OSEK COM 3.03), jeweils mit booleschen Ausgängen <code>true</code> und <code>false</code>.</li>\n<li><code>Evaluation of TRANSMISSION MODE Selector (TMS) for I-PDU</code>: Sammel- und Auswahllogik zur Aggregation der Signalzustände für den I-PDU-Sendemodus.</li>\n<li><strong>Zielstrukturen / Datenpfade</strong>:</li>\n<li><code>update signal in I-PDU</code>: Pfade zum Schreiben des Signalwerts in das I-PDU-Pufferlayout.</li>\n<li>Sende-I-PDU (<code>IPDU_k</code>): Aggregiertes PDU-Layout bestehend aus den Signalfeldern <code>Signal 1</code>, <code>Signal 2</code> und <code>Signal 3</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Bei Bereitstellung eines Sendesignals (<code>Signal 1</code>, <code>Signal 2</code>) verzweigt der Signalfluss: Ein Zweig aktualisiert das Signal direkt im PDU-Puffer (<code>update signal in I-PDU</code>), der andere speist den Block zur Auswertung der Transmission-Mode-Bedingung <code>C(s, IPDU_k)</code>.</li>\n<li>Das Signal-Gateway nimmt das gewandelte Signal (<code>From RX side – after endianness conversion and sign extension</code>) auf und speist über seinen TX-Ausgang sowohl die Bedingungsauswertung <code>C(s_j, IPDU_k)</code> als auch den Pufferaktualisierungspfad (<code>update signal in I-PDU</code>) für <code>Signal 3</code>. Der Pfad vor Konvertierung läuft als RX-Eingang ohne interne Durchleitung in den Gateway-Block.</li>\n<li>Die Bedingungsauswertungen liefern jeweils einen booleschen Status (<code>true</code> / <code>false</code>) an die vertikale Aggregationsschiene.</li>\n<li>Die Aggregationsschiene leitet die Einzelauswertungen an den <code>Evaluation of TRANSMISSION MODE Selector (TMS) for I-PDU</code> weiter.</li>\n<li>Der TMS bestimmt den aktuellen Übertragungsmodus der Sende-I-PDU und steuert deren Gesamtsendung.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Diagramm definiert die funktionale Kopplung von Signalaktualisierung (<code>update signal in I-PDU</code>) und Übertragungsmodusselektion (TMS).</li>\n<li>Zeigt das Routingverhalten im Signal-Gateway für Weiterleitungssignale auf TX-I-PDUs.</li>\n<li>Bedingungen zur Bestimmung des Transmission Mode Selector basieren auf den Filterdefinitionen nach OSEK COM 3.03.</li>\n</ul>"}], "trans": [{"from": "FIG-e04ccc609db691e8", "to": "FIG-50f006e5c8dd4f97", "fr": "R2.1.20", "tr": "R3.0.7", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>Signal based gateway</strong>: Die internen gestrichelten Pfade entfallen; ein RX-Pfad („From RX side – after endianness conversion and sign extension“) führt nun in den Gateway-Block, der einen gemeinsamen TX-Ausgang bereitstellt, welcher sich in die TMS-Evaluierung und die I-PDU-Aktualisierung verzweigt. Der zweite RX-Pfad („From RX side – before endianness conversion and sign extension“) läuft als separate Eingangsleitung am Block vorbei bzw. endet stumpf am Blockrand.</li>\n<li><strong>Beschriftung</strong>: Tippfehlerkorrekturen in allen Hinweistexten von „Condtions“ zu „Conditions“ sowie von „endianess“ zu „endianness“.</li>\n<li><strong>Layout/Rendering</strong>: Überlappung der Indizes in den Formeln <code>C(si, IPDUk)</code> / <code>C(sj, IPDUk)</code> durch geänderte Schrift- und Zeichensatzeinbettung.</li>\n</ul>"}, {"from": "FIG-50f006e5c8dd4f97", "to": "FIG-0b01ac56cc9b1123", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-0b01ac56cc9b1123", "to": "FIG-4db611d5ba06f74d", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
